// Command gen writes each engine's form of the workloads in st: bytecode for
// the VM (vmplc, vmcalc), transpiled Go (goplc, gocalc) and the source the
// evaluator parses on the device (evalsrc).
//
//	go generate ./...        # from embedded/bench
//	go run ./gen -check      # fails if a generated file is out of date
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"strings"

	"github.com/apiarytech/beedance/compiler"
	"github.com/apiarytech/beedance/embedded"
	"github.com/apiarytech/beedance/lexer"
	"github.com/apiarytech/beedance/object"
	"github.com/apiarytech/beedance/parser"
	_ "github.com/apiarytech/beedance/stdlib" // the built-in functions
	"github.com/apiarytech/beedance/transpiler"
)

// workloads are the ST files in st, by name.
var workloads = []string{"plc", "calc"}

func main() {
	check := flag.Bool("check", false, "write nothing; fail if a generated file is out of date")
	flag.Parse()
	files, err := generate()
	if err == nil {
		err = write(files, *check)
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "gen:", err)
		os.Exit(1)
	}
}

// generate returns each generated file's content by path.
func generate() (map[string][]byte, error) {
	object.FinalizeBuiltins()
	files := map[string][]byte{}
	var src strings.Builder
	src.WriteString("// Code generated by gen from st/*.st. DO NOT EDIT.\n\n")
	src.WriteString("// Package evalsrc holds the workloads' source, which the evaluator parses\n// on the device.\npackage evalsrc\n")
	for _, w := range workloads {
		text, err := os.ReadFile(filepath.Join("st", w+".st"))
		if err != nil {
			return nil, err
		}
		st := strings.ReplaceAll(string(text), "\r", "")
		parse := func() *parser.Parser { return parser.New(lexer.New(st)) }
		p := parse()
		prog := p.ParseProgram()
		if errs := p.Errors(); len(errs) > 0 {
			return nil, fmt.Errorf("%s.st: %s", w, strings.Join(errs, "; "))
		}
		cp, err := compiler.NewCompilerWithBuiltins(object.Builtins).CompileProgramUnit(prog, "Main")
		if err != nil {
			return nil, fmt.Errorf("%s.st: %v", w, err)
		}
		var vm bytes.Buffer
		// An interval of 1 ns: Run never sleeps, so scans run back to back.
		if err := embedded.GenerateEmbeddedProgram(&vm, cp, embedded.ProgramOptions{Package: "vm" + w, Interval: 1, StackSize: 256, MaxFrames: 32}); err != nil {
			return nil, err
		}
		code, err := format.Source(vm.Bytes())
		if err != nil {
			return nil, err
		}
		files[filepath.Join("vm"+w, "program.go")] = code

		// The transpiler keeps state in the AST, so it gets a fresh one.
		p = parse()
		code, err = transpiler.GoFileWith(p.ParseProgram(), transpiler.Options{Package: "go" + w, HostBinding: true, CompactImage: true})
		if err != nil {
			return nil, fmt.Errorf("%s.st: %v", w, err)
		}
		files[filepath.Join("go"+w, "program.go")] = append([]byte("// Code generated by gen from st/"+w+".st. DO NOT EDIT.\n\n"), code...)

		fmt.Fprintf(&src, "\n// %s is st/%s.st.\nconst %s = %q\n", strings.ToUpper(w[:1])+w[1:], w, strings.ToUpper(w[:1])+w[1:], st)
	}
	code, err := format.Source([]byte(src.String()))
	if err != nil {
		return nil, err
	}
	files[filepath.Join("evalsrc", "evalsrc.go")] = code
	return files, nil
}

// write writes files, or with check compares them with what is on disk.
func write(files map[string][]byte, check bool) error {
	for path, code := range files {
		if check {
			have, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			if !bytes.Equal(bytes.ReplaceAll(have, []byte("\r\n"), []byte("\n")), code) {
				return fmt.Errorf("%s is out of date: go generate ./...", path)
			}
			continue
		}
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(path, code, 0o644); err != nil {
			return err
		}
	}
	return nil
}
